using System;using System.Net;using System.Net.Sockets;using System.Threading;namespace ServiceTool{internal static class ServiceTcpProbeTests{[STAThread]static int Main(){try{int n=0;foreach(var ip in new[]{IPAddress.Loopback,IPAddress.IPv6Loopback}){var server=new TcpListener(ip,0);server.Start();try{var listener=new ServiceListener{Address=ip.ToString(),Port=((IPEndPoint)server.LocalEndpoint).Port};if(ip.AddressFamily==AddressFamily.InterNetworkV6)listener.Address="[::1]";var info=new ServiceEndpointInfo();info.Listeners.Add(listener);ServiceEndpoints.AddTcpChecks(info);if(info.Checks.Count!=1)throw new Exception("Endpoint not detected");var result=ServiceProbe.Check(info.Checks[0],CancellationToken.None);if(!result.Responded||!result.Message.Contains("команды не отправлялись"))throw new Exception(result.Message);using(var accepted=server.AcceptTcpClient()){accepted.ReceiveTimeout=200;if(accepted.GetStream().ReadByte()!=-1)throw new Exception("Unexpected payload");}n+=3;}finally{server.Stop();}}bool denied=false;try{ServiceProbe.Check("tcp://8.8.8.8:80/",CancellationToken.None);}catch(ArgumentException){denied=true;}if(!denied)throw new Exception("External address allowed");n++;Console.WriteLine("PASS: "+n+" TCP IPv4/IPv6 discovery/connect/no payload/external denial checks.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}